if($invoiceTaxYear&&\Kulturhus\Verein\TaxCatalog::assignmentUsesFallback($invoiceTaxYear))$invoiceAccountingOptions['account_help']=$invoiceEntryText('Für die Zuordnung dieses historischen Belegs wird der aktuelle geprüfte SKR42-Katalog {year} verwendet. Das Rechnungsjahr bleibt erhalten; ein Export für das historische Jahr wird separat geprüft.',['year'=>$invoiceTaxCatalogYear]);
